<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {getVisitorState,postVisitor,type VAlert,type VPayload} from './visitor-content-api';
const payload=ref<VPayload|null>(null),message=ref(''),editing=ref<VAlert|null>(null),form=ref<any>({text:'',level:'注意',enabled:true,startAt:'',endAt:'',placeCodes:[],contentIds:[]});
async function load(){payload.value=await getVisitorState();}onMounted(load);const active=computed(()=>payload.value?.state.alerts.filter(a=>!a.deletedAt)||[]);
function edit(a?:VAlert){editing.value=a||null;form.value=a?{text:a.text,level:a.level,enabled:a.enabled,startAt:a.startAt||'',endAt:a.endAt||'',placeCodes:[...a.placeCodes],contentIds:[...a.contentIds]}:{text:'',level:'注意',enabled:true,startAt:'',endAt:'',placeCodes:[],contentIds:[]};}
async function save(){try{await postVisitor('/alerts/save',{id:editing.value?.id,expected_version:editing.value?.version,text:form.value.text,level:form.value.level,enabled:form.value.enabled,start_at:form.value.startAt||null,end_at:form.value.endAt||null,place_codes:form.value.placeCodes,content_ids:form.value.contentIds});message.value='现场提醒已保存';edit();await load();}catch(e){message.value=(e as Error).message;}}
async function toggle(a:VAlert){try{await postVisitor(`/alerts/${a.id}/toggle`,{expected_version:a.version,enabled:!a.enabled});await load();}catch(e){message.value=(e as Error).message;}}
</script>
<template><div class="workspace-page"><div class="workspace-title"><div><p class="kicker">短期变化</p><h1>现场提醒</h1><p>提醒可启停和设定生效时间，不必改写正文。</p></div><button @click="edit()">新建提醒</button></div><p v-if="message" class="inline-message">{{message}}</p><div class="alert-admin-list"><article v-for="a in active" :key="a.id"><span class="alert-level" :class="'level-'+a.level">{{a.level}}</span><div><strong>{{a.text}}</strong><small>地点 {{a.placeCodes.join('、')||'—'}} · 内容 {{a.contentIds.length}} 项</small></div><span class="status-chip" :class="a.enabled?'published':'hidden'">{{a.enabled?'启用':'关闭'}}</span><button class="secondary" @click="edit(a)">编辑</button><button class="quiet" @click="toggle(a)">{{a.enabled?'关闭':'启用'}}</button></article></div><section class="alert-form"><h2>{{editing?'编辑提醒':'新建提醒'}}</h2><div class="form-grid"><label class="wide">提醒内容<textarea v-model="form.text" maxlength="500" rows="3"></textarea></label><label>级别<select v-model="form.level"><option>提示</option><option>注意</option><option>重要</option></select></label><label class="inline-check"><input v-model="form.enabled" type="checkbox">启用</label><label>开始时间<input v-model="form.startAt" type="datetime-local"></label><label>结束时间<input v-model="form.endAt" type="datetime-local"></label></div><h3>关联地点</h3><div class="batch-grid compact"><label v-for="p in payload?.places.filter(p=>!p.deleted_at&&!p.duplicate_of_place_id)" :key="p.code"><input v-model="form.placeCodes" type="checkbox" :value="p.code">{{p.name}}</label></div><h3>关联游客内容</h3><div class="batch-grid compact"><label v-for="c in payload?.state.contents.filter(c=>!c.deletedAt)" :key="c.id"><input v-model="form.contentIds" type="checkbox" :value="c.id">{{c.draft.title}}</label></div><button @click="save">保存提醒</button></section></div></template>
